import { describe, expect, it } from "vitest"
import { invoiceTotals, type InvoiceLine } from "./billing"
import { invoiceTotals as erpInvoiceTotals } from "../workforce/billing"

/**
 * NFR-05: invoice totals recompute to the cent from their lines, on thousands
 * of random invoices. The check works in whole centimes, independently of the
 * floating-point code it verifies.
 */

/** Small seeded generator, so a failure always replays the same invoice. */
function mulberry32(seed: number) {
  let a = seed
  return () => {
    a |= 0
    a = (a + 0x6d2b79f5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

const RATES = [0, 7, 10, 14, 20]

function randomInvoice(rand: () => number): { lines: InvoiceLine[]; cents: { qty: number; unit: number; rate: number }[] } {
  const n = 1 + Math.floor(rand() * 8)
  const cents = Array.from({ length: n }, () => ({
    qty: 1 + Math.floor(rand() * 12),
    // a line now and then is a discount (negative), as on Nexora's invoices
    unit: Math.round((rand() < 0.15 ? -1 : 1) * (1 + rand() * 1_500_000)),
    rate: RATES[Math.floor(rand() * RATES.length)]!,
  }))
  return { cents, lines: cents.map((c, i) => ({ label: `Line ${i + 1}`, quantity: c.qty, unitPrice: c.unit / 100, vatRate: c.rate })) }
}

describe("invoice totals to the cent (NFR-05)", () => {
  it("recomputes subtotal, VAT per rate and total on 5,000 random invoices", () => {
    const rand = mulberry32(20261013)
    for (let k = 0; k < 5000; k++) {
      const { lines, cents } = randomInvoice(rand)
      const t = invoiceTotals(lines)
      const base = new Map<number, number>()
      let subtotal = 0
      for (const c of cents) {
        subtotal += c.qty * c.unit
        base.set(c.rate, (base.get(c.rate) ?? 0) + c.qty * c.unit)
      }
      const vat = [...base.entries()].reduce((s, [rate, b]) => s + Math.round((b * rate) / 100), 0)
      const ctx = `invoice ${k}: ${JSON.stringify(cents)}`
      expect(Math.round(t.subtotal * 100), ctx).toBe(subtotal)
      expect(Math.round(t.vat * 100), ctx).toBe(vat)
      expect(Math.round(t.total * 100), ctx).toBe(subtotal + vat)
      // the stored amounts never carry more than two decimals
      for (const v of [t.subtotal, t.vat, t.total]) expect(Math.abs(v * 100 - Math.round(v * 100)), ctx).toBeLessThan(1e-6)
    }
  })

  it("does the same for the companies' invoices in the ERP (half a centime rounds away from zero)", () => {
    const rand = mulberry32(42)
    const away = (x: number) => Math.sign(x) * Math.round(Math.abs(x))
    for (let k = 0; k < 5000; k++) {
      const { cents } = randomInvoice(rand)
      const lines = cents.map((c, i) => ({ id: `l${i}`, description: `Line ${i + 1}`, quantity: c.qty, unitPrice: c.unit / 100, taxRate: c.rate }))
      const t = erpInvoiceTotals({ lines, taxRate: 20 } as never)
      const base = new Map<number, number>()
      let subtotal = 0
      for (const c of cents) {
        subtotal += c.qty * c.unit
        base.set(c.rate, (base.get(c.rate) ?? 0) + c.qty * c.unit)
      }
      const tax = [...base.entries()].reduce((s, [rate, b]) => s + away((b * rate) / 100), 0)
      const ctx = `ERP invoice ${k}: ${JSON.stringify(cents)}`
      expect(Math.round(t.subtotal * 100), ctx).toBe(subtotal)
      expect(Math.round(t.tax * 100), ctx).toBe(tax)
      expect(Math.round(t.total * 100), ctx).toBe(subtotal + tax)
    }
  })
})
